package com.hbm.client.reactor.rbmk.failure;
import com.mojang.blaze3d.platform.GlStateManager;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.Camera;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.particle.*;import net.minecraft.client.renderer.GameRenderer;import net.minecraft.client.renderer.texture.TextureManager;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;
/** Original ParticleRBMKFlame, including authored frame modulo and camera-basis offset, yaw-only billboard, additive/no-fog pass. */
final class RbmkFlameParticle extends Particle {
 private static final ParticleRenderType TYPE=new ParticleRenderType(){@Override public BufferBuilder begin(Tesselator tess,TextureManager textures){RenderSystem.setShader(GameRenderer::getPositionTexColorShader);RenderSystem.setShaderTexture(0,ResourceLocation.parse("hbm:textures/particle/rbmk_fire.png"));RenderSystem.enableBlend();RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA,GlStateManager.DestFactor.ONE);RenderSystem.depthMask(false);RenderSystem.disableCull();return tess.begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.PARTICLE);}};private final float scale;
 RbmkFlameParticle(ClientLevel world,double x,double y,double z,int life){super(world,x,y,z);lifetime=life;scale=random.nextFloat()+1;hasPhysics=false;}@Override public void tick(){xo=x;yo=y;zo=z;if(age++>=lifetime)remove();}@Override public ParticleRenderType getRenderType(){return TYPE;}@Override public void render(VertexConsumer out,Camera camera,float partial){if(com.hbm.client.render.WorldEffectParticles.draw(com.hbm.client.render.WorldEffectParticles.RBMK_FIRE,vertices->sourceRender(vertices,camera,partial)))return;sourceRender(out,camera,partial);}private void sourceRender(VertexConsumer out,Camera camera,float partial){if(age>lifetime)age=lifetime;int texture=age*5%14;float u0=texture%5/14F,u1=u0+1F/14;alpha=1;if(age<20)alpha=age/20F;if(age>lifetime-20)alpha=(lifetime-age)/20F;alpha*=.5F;var eye=camera.getPosition();double yaw=camera.getYRot()*Math.PI/180,pitch=camera.getXRot()*Math.PI/180,cos=Math.cos(yaw),sin=Math.sin(yaw);float px=(float)(Mth.lerp(partial,xo,x)-eye.x+cos),py=(float)(Mth.lerp(partial,yo,y)-eye.y+Math.cos(pitch)),pz=(float)(Mth.lerp(partial,zo,z)-eye.z+sin);float[] xs={-scale-1,-scale-1,scale-1,scale-1},ys={-scale*2,scale*2,scale*2,-scale*2},us={u1,u1,u0,u0},vs={1,0,0,1};for(int i=0;i<4;i++)out.addVertex(px+(float)(xs[i]*cos),py+ys[i],pz+(float)(xs[i]*sin)).setUv(us[i],vs[i]).setColor(1F,1F,1F,alpha).setLight(240);}
}
